// SCHEMA.md 1: flowwatch/{unit}/sensor/{name}  parse unit + measurement
const path = msg.topic.split('/');
const unit = path[1];
const name = path[3];
const body = msg.payload || {};

// SCHEMA.md 2: measurement name + tag unit_id; payload [fields, tags]
msg.measurement = name; // 'ultrasonic' | 'waterlevel'
msg.payload = name === 'ultrasonic'
    ? [{ distance_cm: body.cm }, { unit_id: unit }]
    : [{ level_cm: body.cm }, { unit_id: unit }];
// SCHEMA.md 2: one bucket per unit, chosen per unit from the topic
msg.bucket = 'flowwatch_' + unit;
return msg;

// SCHEMA.md 1: flowwatch/{unit}/alert/{kind}
const path = msg.topic.split('/');
const unit = path[1];
const kind = path[3];
const b = msg.payload || {};

// SCHEMA.md 4: alert topic -> event_type + detail
let event_type, detail;
switch (kind) {
    case 'blockage':
        event_type = 'blockage_detected';
        detail = 'distance_cm=' + b.distance_cm;
        break;
    case 'flood':
        event_type = 'flood_alert';
        detail = 'level_cm=' + b.level_cm;
        break;
    case 'fault':
        event_type = 'fault';
        detail = b.code; // SCHEMA.md 4 fault code
        break;
    default:
        event_type = kind;
        detail = JSON.stringify(b);
}

msg.topic = 'INSERT INTO events (unit_id, event_type, detail) VALUES (?, ?, ?);';
msg.payload = [unit, event_type, detail];
return msg;

// SCHEMA.md 1: flowwatch/{unit}/control/manual
const path = msg.topic.split('/');
const unit = path[1];
const b = msg.payload || {};

// SCHEMA.md 4: manual mode activation/release logged as events
const event_type = b.action === 'release' ? 'manual_mode_released' : 'manual_mode_activated';
msg.topic = 'INSERT INTO events (unit_id, event_type, detail) VALUES (?, ?, ?);';
msg.payload = [unit, event_type, 'requested_by=' + (b.requested_by || 'unknown')];
return msg;

// SCHEMA.md 1: flowwatch/{unit}/status/{kind}  (actuator | connectivity)
// FR-8: discrete events with timestamps. Log only on state transitions.
const path = msg.topic.split('/');
const unit = path[1];
const kind = path[3];
const b = msg.payload || {};

const prev = context.get('status_' + unit) || {};
let event_type = null;
let detail = null;

if (kind === 'actuator') {
    // SCHEMA.md 4: cycle_complete = returned to STANDBY after a cycle ran
    if (b.state === 'STANDBY' &&
        ['LIFTING', 'FLIPPING', 'LOWERING'].indexOf(prev.actuator) !== -1) {
        event_type = 'cycle_complete';
        detail = 'state=STANDBY';
    }
    prev.actuator = b.state;
} else if (kind === 'connectivity') {
    // SCHEMA.md 4: wifi_lost / wifi_restored on wifi boolean transitions
    if (b.wifi === false && prev.wifi === true) {
        event_type = 'wifi_lost';
        detail = 'wifi=false';
    } else if (b.wifi === true && prev.wifi === false) {
        event_type = 'wifi_restored';
        detail = 'wifi=true';
    }
    prev.wifi = b.wifi;
}

context.set('status_' + unit, prev);

if (!event_type) {
    return null; // not a transition -- retained/Live same-state messages are ignored
}

msg.topic = 'INSERT INTO events (unit_id, event_type, detail) VALUES (?, ?, ?);';
msg.payload = [unit, event_type, detail];
return msg;

// ARCHITECTURE.md 1: read-only history endpoint
const q = msg.req.query || {};
const unit = q.unit || 'unit1';
const measurement = q.measurement || 'waterlevel'; // SCHEMA.md 2
const field = measurement === 'ultrasonic' ? 'distance_cm' : 'level_cm';
const limit = Math.min(parseInt(q.limit) || 100, 1000);

const bucket = 'flowwatch_' + unit; // SCHEMA.md 2: one bucket per unit

msg.query = [
    'from(bucket: "' + bucket + '")',
    '  |> range(start: -24h)',
    '  |> filter(fn: (r) => r._measurement == "' + measurement + '")',
    '  |> filter(fn: (r) => r._field == "' + field + '")',
    '  |> sort(columns: ["_time"])' + '  |> limit(n: ' + limit + ')'
].join('\n');
return msg;

const rows = msg.payload || [];
msg.payload = rows.map(function (r) {
    return { ts: r._time, value: r._value, unit_id: r.unit_id || 'unit1' };
});
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const q = msg.req.query || {};
const unit = q.unit || null;
const limit = Math.min(parseInt(q.limit) || 50, 500);

// SCHEMA.md 3: events table; optional per-unit filter
let sql = 'SELECT id, unit_id, event_type, detail, created_at FROM events';
let params = [];
if (unit) { sql += ' WHERE unit_id = ?'; params.push(unit); }
sql += ' ORDER BY created_at DESC LIMIT ?';
params.push(limit);

msg.topic = sql;
msg.payload = params;
return msg;
